SourceCode.Declaration:
/// <summary>
/// Response data contract class for <c>METAutoPostInvJournalService</c> class.
/// </summary>
[DataContractAttribute]
class METAutoPostInvJournalResponseContract
{
    private boolean     success;
    private str         message;
    private InventJournalId journalId;

}

Method.Source:
    /// <summary>
    /// Method used to specify the posting result of a inventory journal as string value
    /// </summary>
    /// <param name = "_message">posting result as a message</param>
    /// <returns>posting result/error message if any</returns>
    [
        DataMemberAttribute('@MET:Message'),
        SysOperationLabelAttribute(literalstr("@MET:Message"))
    ]
    public str parmMessage(str _message = message)
    {
        if (!prmIsDefault(_message))
        {
            message = _message;
        }

        return message;
    }

    /// <summary>
    /// Method to return boolean posting result
    /// </summary>
    /// <param name = "_success">posting result</param>
    /// <returns>True is success/false if posting fails</returns>
    [
        DataMemberAttribute('@MET:Result'),
        SysOperationLabelAttribute(literalstr("@MET:Result"))
    ]
    public Boolean parmSuccess(Boolean _success = success)
    {
        if (!prmIsDefault(_success))
        {
            success = _success;
        }

        return success;
    }

    /// <summary>
    /// Method to get/set the journal ID to be posted
    /// </summary>
    /// <param name = "_journalId">inventory journal ID</param>
    /// <returns>inventory journal ID to be posted</returns>
    [
        DataMemberAttribute('@ENG186'),
        SysOperationLabelAttribute(literalstr("@ENG186"))
    ]
    public InventJournalId parmJournalId(InventJournalId _journalId = journalId)
    {
        if (!prmIsDefault(_journalId))
        {
            journalId = _journalId;
        }

        return journalId;
    }
